INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:1f8eecf692f0','بخشنامه','200/7353/ص پ','1405/05/05','تفاهم‌نامه سازمان امور مالیاتی کشور و سازمان نظام پزشکی جمهوری اسلامی .....','تفاهم‌نامه سازمان امور مالیاتی کشور و سازمان نظام پزشکی جمهوری اسلامی ایران در خصوص کسر مالیات علی‌الحساب از حق‌الزحمه و حق‌العمل پزشکان. شماره: ۲۰۰/۷۳۵۳/ص پ، تاریخ صدور: ۱۴۰۵/۰۵/۰۵. مرجع صدور: رئیس کل سازمان امور مالیاتی به همراه مرجع دیگر. موضوع: حذف مالیات تکلیفی پزشکان، دندانپزشکان و جایگزینی آن با کسر ۱۰ درصد مالیات علی‌الحساب از حق‌الزحمه یا حق‌العمل پزشکان توسط مراکز درمانی و واریز به حساب خزانه‌داری کل کشور.','https://www.intamedia.ir/','رئیس کل سازمان امور مالیاتی به همراه مرجع دیگر','معتبر (دائمی)','قانون مالیات‌های مستقیم (احکام مالیاتی قانون بودجه ۱۴۰۵)، ماده ۲۵۵ قانون مالیات‌های مستقیم (مالیات علی‌الحساب)','این تفاهم‌نامه جایگزین سیستم قبلی مالیات تکلیفی پزشکان شده است. بر اساس آن، مراکز درمانی موظف‌اند ۱۰ درصد از حق‌الزحمه یا حق‌العمل پزشکان را به عنوان مالیات علی‌الحساب کسر و به حساب خزانه‌داری کل کشور واریز کنند. این روش شفاف‌تر و دقیق‌تر از سیستم تکلیفی قبلی است و مالیات واقعی بر اساس درآمد واقعی پزشکان محاسبه خواهد شد.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:5703db7d5f03','بخشنامه','30004/ت65384هـ','1405/03/31','تعیین نه درصد (9%) مأخذ محاسبه سایر عوارض و وجوه موضوع تبصره (3) ماده .....','تصویب‌نامه شماره ۳۰۰۰۴/ت۶۵۳۸۴هـ مورخ ۱۴۰۵/۰۳/۳۱ هیئت وزیران: «مأخذ محاسبه سایر عوارض و وجوه موضوع تبصره (۳) ماده (۶۴) اصلاحی قانون مالیات‌های مستقیم مصوب ۱۳۹۴، معادل نه درصد (۹٪) ارزش معاملاتی خواهد بود که با رعایت نصاب مقرر در صدر ماده مذکور تعیین گردیده است. این ضریب تا تصویب ضریب بعدی معتبر است.» ابلاغ شده توسط معاونت درآمدهای مالیاتی سازمان امور مالیاتی کشور.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دارای زمان‌بندی)','تبصره ۳ ماده ۶۴ اصلاحی قانون مالیات‌های مستقیم مصوب ۱۳۹۴','بر اساس این تصویب‌نامه، ضریب ۹ درصدی ارزش معاملاتی برای محاسبه عوارض و وجوه دولتی موضوع تبصره ۳ ماده ۶۴ قانون مالیات‌های مستقیم تعیین شده است. این ضریب تا تصویب ضریب بعدی دارای اعتبار است و مبنای محاسبه سایر عوارض و وجوه دولتی که بر اساس ارزش معاملاتی املاک محاسبه می‌شوند را مشخص می‌کند.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:3e37419015c8','بخشنامه','25460/ت65222هـ','1405/03/20','اصلاح آیین‌نامه اجرایی پذیرش اوراق گواهی اعتبار مولد(گام) در دستگاه‌ها.....','آیین‌نامه اجرایی پذیرش اوراق گواهی اعتبار مولد (گام) در دستگاه‌های اجرایی. تصویب‌نامه شماره ۲۵۴۶۰/ت۶۵۲۲۲هـ. شامل ۱۰ ماده: ماده ۱- تعاریف (اوراق گام: اوراقی که نشان‌دهنده بدهی قطعی متعهد به متقاضی است و با ضمانت موسسه اعتباری صادر می‌شود). ماده ۲- اشخاص بدهکار می‌توانند تا سقف ۵۰٪ از تعهدات پرداخت‌نشده خود را از طریق این اوراق تسویه کنند. ماده ۳- دستگاه‌های مجاز (امور مالیاتی، گمرک، تامین اجتماعی، وزارتخانه‌های نفت و نیرو) موظف به پذیرش اوراق گام بابت بدهی‌هایی نظیر مالیات، حقوق دولتی معادن، حق بیمه، قبوض آب و برق و حقوق ورودی گمرک هستند. ماده ۴- اوراق باید هنگام انتقال دارای سررسید ۳ ماه یا کمتر باشند (با تبصره امکان پذیرش تا ۶ ماه). ماده ۵- ممنوعیت تنزیل در شبکه بانکی. ماده ۹- برات الکترونیکی نیز در حکم اوراق گام است. ماده ۱۰- هزینه تنزیل اوراق گام به عنوان هزینه قابل قبول مالیاتی پذیرفته می‌شود.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','اصل ۱۳۸ قانون اساسی، ماده ۱۹۱ قانون مالیات‌های مستقیم (بخشودگی جرایم)، ماده ۱۴۷ قانون مالیات‌های مستقیم (هزینه قابل قبول مالیاتی)','این آیین‌نامه نحوه تسویه بدهی‌های دولتی توسط بخش خصوصی با استفاده از اوراق گواهی اعتبار مولد (گام) را شرح می‌دهد. اشخاص بدهکار می‌توانند تا ۵۰ درصد از تعهدات پرداخت‌نشده خود (مالیات، حقوق گمرکی، حق بیمه و...) را با این اوراق تسویه کنند. اوراق گام با ضمانت بانکی صادر می‌شوند و دستگاه‌های اجرایی مکلف به پذیرش آن‌ها هستند. هزینه تنزیل این اوراق نیز به عنوان هزینه قابل قبول مالیاتی تلقی می‌شود.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:905f2798bf33','بخشنامه','20877/ت65624هـ','1405/03/11','نصاب معاملات موضوع ماده (3) قانون برگزاری مناقصات مصوب 1383','تصویب‌نامه شماره ۲۰۸۷۷/ت۶۵۶۲۴هـ مورخ ۱۱ خرداد ۱۴۰۵ هیئت وزیران در خصوص تعیین نصاب معاملات موضوع ماده (۳) قانون برگزاری مناقصات مصوب ۱۳۸۳ برای سال ۱۴۰۵: الف- معاملات کوچک: مبالغ تا سقف ۴٬۲۳۰٬۰۰۰٬۰۰۰ ریال (۴۲۳ میلیون تومان). ب- معاملات متوسط: مبالغ بیش از سقف معاملات کوچک تا سقف ۴۲٬۳۰۰٬۰۰۰٬۰۰۰ ریال (۴ میلیارد و ۲۳۰ میلیون تومان). ج- معاملات بزرگ: مبالغی که از ۴۲٬۳۰۰٬۰۰۰٬۰۰۰ ریال تجاوز کنند. نصاب ثبت تجمیعی گزارش فصلی (۵٪ نصاب معاملات کوچک): ۲۱۱٬۵۰۰٬۰۰۰ ریال. نصاب ثبت دارایی به عنوان هزینه استهلاک (۱۰٪ نصاب معاملات کوچک): ۴۲۳٬۰۰۰٬۰۰۰ ریال.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دارای زمان‌بندی)','ماده ۳ قانون برگزاری مناقصات مصوب ۱۳۸۳، ماده ۱۴۹ اصلاحی قانون مالیات‌های مستقیم، ماده ۱۲ مقررات و ضوابط اجرایی هزینه استهلاک دارایی‌ها','این تصویب‌نامه نصاب معاملات سال ۱۴۰۵ را بر اساس ماده ۳ قانون برگزاری مناقصات تعیین می‌کند. سقف معاملات کوچک ۴۲۳ میلیون تومان (افزایش حدود ۶۵٪ نسبت به سال ۱۴۰۴ که ۲۸۵ میلیون تومان بود) است. این نصاب‌ها تعیین‌کننده نوع معامله (خرید مستقیم، استعلام بها یا مناقصه) و همچنین حد نصاب ثبت تجمیعی معاملات در گزارش فصلی مالیاتی و حد استهلاک دارایی‌ها هستند.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:600b3f35914f','بخشنامه','17334/ت65641هـ','1405/03/03','تمدید تضمین های مالی تودیع شده (ضمانتنامه ها و وثیقه های گمرکی و دریاف.....','بخشنامه شماره ۱۷۳۳۴/ت۶۵۶۴۱هـ در خصوص تمدید تضمین‌های مالی تودیع‌شده (ضمانت‌نامه‌ها و وثیقه‌های گمرکی و دریافتی). گمرک ایران اختیار تمدید ضمانت‌نامه‌های بانکی موضوع ماده ۴۵ قانون امور گمرکی را که پرونده‌های اختلافی آن به کمیسیون‌های رسیدگی به اختلافات گمرکی ارجاع می‌شوند، به گمرکات اجرایی تفویض می‌کند. در مواردی که صاحبان کالا مبلغ مابه‌التفاوت استنباطی گمرک را به صورت ضمانت‌نامه بانکی تودیع و با رعایت مفاد ماده ۱۴۴ قانون امور گمرکی ارجاع پرونده به کمیسیون‌ها را تقاضا می‌نمایند، اختیار تمدید ضمانت‌نامه‌های مأخوذه (صرفاً به میزان تفاوت و جریمه احتمالی) تا زمان اعلام نتیجه رسیدگی به مدیریت آن گمرک تفویض می‌گردد.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دارای زمان‌بندی)','ماده ۴۵ قانون امور گمرکی (تودیع مبلغ مابه‌التفاوت استنباطی به صورت ضمانت‌نامه)، ماده ۱۴۴ قانون امور گمرکی (ارجاع به کمیسیون‌های رسیدگی به اختلافات گمرکی)','این بخشنامه به گمرکات اجرایی اختیار می‌دهد تا ضمانت‌نامه‌های بانکی تودیع‌شده توسط صاحبان کالا را در موارد اختلافی تمدید کنند، بدون نیاز به ارجاع به گمرک مرکزی. هدف این بخشنامه کاهش مراجعات حضوری، تمرکززدایی از ستاد مرکزی گمرک و تسهیل کار ذی‌نفعان است. تمدید ضمانت‌نامه صرفاً به میزان مابه‌التفاوت و جریمه احتمالی انجام می‌شود و تا زمان صدور رأی نهایی کمیسیون حل اختلاف اعتبار دارد.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:aedd4916ad6c','بخشنامه','5681/ت63853هـ','1405/02/06','اصلاح تصويب نامه شماره 165420/ت63853هـ مورخ 1404/09/30 [با موضوع تعيين.....','تصویب‌نامه شماره ۵۶۸۱/ت۶۳۸۵۳هـ در خصوص اصلاح تصویب‌نامه شماره ۱۶۵۴۲۰/ت۶۳۸۵۳هـ مورخ ۱۴۰۴/۰۹/۳۰ با موضوع تعیین فهرست مواد و محصولات معدنی، صنایع معدنی فلزی و غیرفلزی و محصولات نفتی، پتروشیمی و پالایشگاهی مشمول بند الزام خرید از بورس کالا. این اصلاحیه شامل به‌روزرسانی فهرست ۷۵۶ ردیف کالای خام و نیمه‌خام معدنی و پتروشیمی است.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تصویب‌نامه شماره ۱۶۵۴۲۰/ت۶۳۸۵۳هـ مورخ ۱۴۰۴/۰۹/۳۰ (فهرست مواد و محصولات معدنی و پتروشیمی مشمول الزام خرید از بورس کالا)','این تصویب‌نامه اصلاحیه‌ای بر فهرست قبلی کالاهای معدنی و پتروشیمی است که مشمول الزام خرید و فروش از بورس کالا هستند. هدف این مصوبه شفاف‌سازی و به‌روزرسانی فهرست کالاهای خام و نیمه‌خام معدنی، فلزی و غیرفلزی و محصولات نفتی و پتروشیمی است تا معاملات این کالاها از طریق بورس کالا انجام شود.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:0df520ef90e4','بخشنامه','1183/ت65504هـ','1405/01/20','اعطاي تسهيلات سرمايه در گردش با هدف حمايت از بنگاههاي اقتصادي آسيب ديد.....','بخشنامه شماره ۱۱۸۳/ت۶۵۵۰۴هـ در خصوص اعطای تسهیلات سرمایه در گردش با هدف حمایت از بنگاه‌های اقتصادی آسیب‌دیده. سقف تسهیلات سرمایه در گردش قابل اعطا: ۱- واحدهای تولیدی فعال: حداکثر معادل ۹۰ درصد فروش سال گذشته. ۲- واحدهای تولیدی جدید یا غیرفعال یا دارای طرح توسعه‌ای: برای سال اول حداکثر معادل ۹۰ درصد پیش‌بینی فروش. ۳- شرکت‌های بازرگانی، خدماتی و پیمانکاری فعال: حداکثر معادل ۶۰ درصد بالاترین میزان فروش هر دوره مندرج در صورت‌های مالی حسابرسی‌شده در طول سه سال گذشته. ۴- شرکت‌های بازرگانی، خدماتی و پیمانکاری جدید یا غیرفعال: برای سال اول حداکثر معادل ۶۰ درصد پیش‌بینی فروش.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','آیین‌نامه رعایت شاخص‌های مالی در اعطای تسهیلات سرمایه در گردش به اشخاص حقیقی و حقوقی توسط بانک‌های دولتی، قانون عملیات بانکی (بدون ربا)','این بخشنامه با هدف حمایت از بنگاه‌های اقتصادی آسیب‌دیده صادر شده و سقف تسهیلات سرمایه در گردش را برای واحدهای تولیدی ۹۰ درصد فروش و برای شرکت‌های بازرگانی و خدماتی ۶۰ درصد فروش تعیین می‌کند. تمایز بین واحدهای تولیدی و غیرتولیدی در سقف تسهیلات نشان‌دهنده اولویت‌دهی به بخش تولید است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:789d76f8f7de','بخشنامه','181558/ت65283هـ','1404/10/29','اصلاح ماده (4) آیین‌نامه اجرایی بند (ت) ماده (78) قانون برنامه پنج‌سال.....','تصویب‌نامه شماره ۱۸۱۵۵۸/ت۶۵۲۸۳هـ در خصوص اصلاح ماده (۴) آیین‌نامه اجرایی بند (ت) ماده (۷۸) قانون برنامه پنج‌ساله هفتم پیشرفت جمهوری اسلامی ایران. موضوع آیین‌نامه: توسعه اقتصاد ورزش و جذب و تشویق حامیان بخش غیردولتی جهت فعالیت در حوزه ورزش. ماده ۴ (اصلاحي ۱۴۰۴/۱۰/۲۱)- مربوط به اعتبارات و نحوه تخصیص منابع برای توسعه ورزش همگانی و قهرمانی.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دارای زمان‌بندی)','بند (ت) ماده ۷۸ قانون برنامه پنج‌ساله هفتم پیشرفت جمهوری اسلامی ایران (۱۴۰۳-۱۴۰۷)، آیین‌نامه اجرایی بند (ت) ماده ۷۸','این تصویب‌نامه ماده ۴ آیین‌نامه اجرایی بند (ت) ماده ۷۸ قانون برنامه هفتم را اصلاح می‌کند. موضوع اصلی این آیین‌نامه توسعه اقتصاد ورزش و جذب سرمایه‌گذاران و حامیان بخش خصوصی برای فعالیت در حوزه ورزش است. اصلاح ماده ۴ مربوط به نحوه تخصیص اعتبارات و منابع مالی این حوزه می‌باشد.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:e7dea211961d','بخشنامه','179771/ت65270هـ','1404/10/24','اصلاح تبصره (1) اصلاحی ماده (10) آئین نامه اجرایی تبصره (1) ماده (149).....','تصویب‌نامه شماره ۱۷۹۷۷۱/ت۶۵۲۷۰هـ در خصوص اصلاح تبصره (۱) اصلاحی ماده (۱۰) آیین‌نامه اجرایی تبصره (۱) ماده (۱۴۹) اصلاحی قانون مالیات‌های مستقیم. ماده ۱۰ آیین‌نامه: «بنگاه‌های تولیدی که در زمان تجدید ارزیابی دارایی‌های خود، دارای زیان انباشته باشند، در صورتی که با رعایت مقررات قانونی نسبت به تهاتر زیان یاد شده از محل مازاد تجدید ارزیابی اقدام نمایند، مشمول مالیات نخواهند بود.» اصلاحیه: پوشش زیان از محل مازاد تجدید ارزیابی، انتقال این مازاد به حساب سود و زیان یا اندوخته یا توزیع آن به هر شکل بین صاحبان سهام مجاز شمرده شد.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره ۱ ماده ۱۴۹ اصلاحی قانون مالیات‌های مستقیم مصوب ۱۳۹۴، آیین‌نامه اجرایی تبصره ۱ ماده ۱۴۹ (مصوب ۱۳۹۴)','این اصلاحیه به بنگاه‌های تولیدی که دارای زیان انباشته هستند اجازه می‌دهد مازاد حاصل از تجدید ارزیابی دارایی‌ها را برای تهاتر زیان انباشته به کار گیرند و از پرداخت مالیات بر این مقدار معاف شوند. همچنین امکان انتقال مازاد به حساب سود و زیان، اندوخته یا توزیع بین صاحبان سهام نیز فراهم شده است. هدف این مصوبه تسهیل به‌روزرسانی ارزش دارایی‌های شرکت‌ها و اصلاح ساختار مالی بنگاه‌های تولیدی است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:909ea6c49623','بخشنامه','171266/ت65050هـ','1404/10/09','آیین نامه اجرایی بند (2) تبصره (4) ماده (34) اصلاحی قانون ثبت (موضوع ب.....','آیین‌نامه اجرایی بند (۲) تبصره (۴) ماده (۳۴) اصلاحی قانون ثبت. تصویب‌نامه شماره ۱۷۱۲۶۶/ت۶۵۰۵۰هـ. ماده ۳۴ قانون ثبت: «در مورد کلیه معاملات رهنی و شرطی و دیگر معاملات مذکور در ماده (۳۳) قانون ثبت، راجع به اموال منقول و غیرمنقول، در صورتی که بدهکار ظرف مهلت مقرر در سند، بدهی خود را نپردازد، طلبکار می‌تواند از طریق صدور اجرائیه وصول طلب خود را توسط دفترخانه تنظیم‌کننده سند، درخواست کند. چنانچه بدهکار ظرف ده روز از تاریخ ابلاغ اجرائیه نسبت به پرداخت بدهی خود اقدام ننماید بنا به تقاضای بستانکار، اداره ثبت پس از ارزیابی تمامی مورد معامله و قطعیت آن، حداکثر ظرف مدت دو ماه از تاریخ قطعیت ارزیابی، با برگزاری مزایده نسبت به وصول مطالبات مرتهن به میزان طلب قانونی وی اقدام و مازاد را به راهن مسترد می‌نماید.» تبصره ۴: در مورد معاملات مذکوره در ماده ۳۴ خسارت تأخیر تأدیه باصل وجه مورد معامله از تاریخ انقضاء مدت حق استرداد تعلق خواهد گرفت.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','ماده ۳۴ قانون ثبت اسناد و املاک (اصلاحی ۱۳۸۶/۱۱/۲۹)، تبصره ۴ ماده ۳۴، قانون اصلاح مواد ۳۴ و ۳۵ قانون ثبت اسناد و املاک، ماده ۳۳ قانون ثبت','این آیین‌نامه اجرایی نحوه اجرای مفاد اسناد رسمی موضوع ماده ۳۴ قانون ثبت را شرح می‌دهد. ماده ۳۴ به معاملات رهنی و شرطی و اجرای آن‌ها از طریق اداره ثبت و مزایده می‌پردازد. تبصره ۴ مربوط به خسارت تأخیر تأدیه است که از تاریخ انقضای مدت حق استرداد تعلق می‌گیرد. آیین‌نامه اجرایی بند ۲ این تبصره جزئیات نحوه اجرا را مشخص می‌کند.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:442af3f7462a','بخشنامه','165420/ت63853ﻫـ','1404/09/30','فهرست مواد و محصولات معدنی، صنایع معدنی فلزی و غیرفلزی و محصولات نفتی،.....','تصویب‌نامه شماره ۱۶۵۴۲۰/ت۶۳۸۵۳هـ مورخ ۱۴۰۴/۰۹/۳۰ هیئت وزیران در خصوص تعیین فهرست مواد و محصولات معدنی، صنایع معدنی فلزی و غیرفلزی و محصولات نفتی، گازی و پتروشیمی به صورت خام و نیمه‌خام مشمول مالیات و عوارض صادراتی. شامل ۷۵۶ ردیف کالای خام و نیمه‌خام معدنی و پتروشیمی. ماده ۴- جداول موضوع این تصویب‌نامه علاوه بر فهرست مواد معدنی خام و کالاهای نفتی مندرج در تصویب‌نامه شماره ۵۸۶۸۳/ات۵۴۵۳۷هـ مورخ ۱۳۹۶/۰۵/۱۶ است.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','ماده ۱۱۹ قانون مالیات‌های مستقیم (مالیات و عوارض صادراتی)، تصویب‌نامه شماره ۵۸۶۸۳/ات۵۴۵۳۷هـ مورخ ۱۳۹۶/۰۵/۱۶ (فهرست قبلی)','این تصویب‌نامه فهرست کالاهای معدنی و پتروشیمی مشمول مالیات و عوارض صادراتی را به‌روزرسانی و تکمیل می‌کند. شامل ۷۵۶ ردیف کالای خام و نیمه‌خام (فلزی، غیرفلزی، نفتی، گازی و پتروشیمی) است که صادرات آن‌ها مشمول مالیات و عوارض می‌باشد. هدف این مصوبه کنترل صادرات مواد خام و تشویق به فرآوری و ارزش افزوده داخلی است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:d115992e3983','بخشنامه','157570/ت64697هـ','1404/09/18','اعلام تعدیل نصاب‌های مندرج در قانون مالیاتهای مستقیم از سوی مرکز آمار .....','تصویب‌نامه شماره ۱۵۷۵۷۰/ت۶۴۶۹۷هـ در خصوص اعلام تعدیل نصاب‌های مندرج در قانون مالیات‌های مستقیم از سوی مرکز آمار ایران. هیئت وزیران به پیشنهاد وزارت امور اقتصادی و دارایی و به استناد تبصره ۱ ماده ۱۴۷ قانون مالیات‌های مستقیم، نصاب‌های مندرج در قانون را بر اساس نرخ تورم اعلامی مرکز آمار ایران تعدیل کرد. نصاب ماده ۱۴۷ از ۵۰ میلیون ریال به ۲۰۰ میلیون ریال و نصاب تبصره ۳ ماده ۱۴۷ نیز از ۵۰ میلیون ریال به ۲۰۰ میلیون ریال افزایش یافت.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره ۱ ماده ۱۴۷ قانون مالیات‌های مستقیم، تبصره ۳ ماده ۱۴۷ قانون مالیات‌های مستقیم','این تصویب‌نامه نصاب‌های مالیاتی قانون مالیات‌های مستقیم را متناسب با نرخ تورم تعدیل می‌کند. مهم‌ترین تغییر، افزایش نصاب ماده ۱۴۷ (هزینه‌های قابل قبول مالیاتی و پرداخت‌های بانکی) از ۵ میلیون تومان به ۲۰ میلیون تومان است. به این معنی که هزینه‌های بیش از ۲۰ میلیون تومان برای پذیرفته شدن به عنوان هزینه قابل قبول مالیاتی باید از طریق سیستم بانکی پرداخت شوند.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:9243dd755629','بخشنامه','149997/ت65055هـ','1404/09/09','اصلاح تصویب نامه شماره 135602/ت57170هـ مورخ 1398/10/22 با موضوع اصلاح.....','تصویب‌نامه شماره ۱۴۹۹۹۷/ت۶۵۰۵۵هـ در خصوص اصلاح تصویب‌نامه شماره ۱۳۵۶۰۲/ت۵۷۱۷۰هـ مورخ ۱۳۹۸/۱۰/۲۲ با موضوع اصلاح ماده ۱۰ آیین‌نامه اجرایی تبصره ۱ ماده ۱۴۹ اصلاحی قانون مالیات‌های مستقیم. ماده ۱۰: «پوشش زیان از محل مازاد تجدید ارزیابی، انتقال این مازاد به حساب سود و زیان یا اندوخته یا توزیع آن به هر شکل بین صاحبان سرمایه، به منزله تحقق درآمد مشمول مالیات تلقی نمی‌شود.» این اصلاحیه جدید تغییرات بیشتری در شرایط تهاتر زیان انباشته از محل مازاد تجدید ارزیابی ایجاد می‌کند.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره ۱ ماده ۱۴۹ اصلاحی قانون مالیات‌های مستقیم مصوب ۱۳۹۴، آیین‌نامه اجرایی تبصره ۱ ماده ۱۴۹، تصویب‌نامه شماره ۱۳۵۶۰۲/ت۵۷۱۷۰هـ مورخ ۱۳۹۸/۱۰/۲۲','این تصویب‌نامه اصلاحیه‌ای بر تصویب‌نامه قبلی (۱۳۵۶۰۲/ت۵۷۱۷۰هـ) است که ماده ۱۰ آیین‌نامه اجرایی تبصره ۱ ماده ۱۴۹ قانون مالیات‌های مستقیم را اصلاح می‌کند. موضوع اصلی امکان پوشش زیان انباشته بنگاه‌های تولیدی از محل مازاد تجدید ارزیابی دارایی‌ها بدون شمول مالیات است. این مصوبه به شرکت‌ها اجازه می‌دهد ساختار مالی خود را با به‌روزرسانی ارزش دارایی‌ها اصلاح کنند.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:616c5656c6f4','بخشنامه','145384/ت64602هـ','1404/09/01','تعیین حق تمبر اوراق و مدارک موضوع مواد (40)، (40 مکرر) و (41) قانون ما.....','تصویب‌نامه شماره ۱۴۵۳۸۴/ت۶۴۶۰۲هـ در خصوص تعیین حق تمبر اوراق و مدارک موضوع مواد (۴۰)، (۴۰ مکرر) و (۴۱) قانون مالیات‌های مستقیم. هیئت وزیران نرخ و نحوه اعمال حق تمبر برای اوراق و مدارک مالیاتی تعیین‌شده در مواد یادشده قانون مالیات‌های مستقیم را مشخص می‌کند. همچنین شامل حق تمبر وکالت‌نامه و قرار دادگاهی موضوع بند ث ماده ۱۴ قانون تأمین مالی تولید و زیرساخت‌ها.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','مواد ۴۰، ۴۰ مکرر و ۴۱ قانون مالیات‌های مستقیم (حق تمبر)، بند ث ماده ۱۴ قانون تأمین مالی تولید و زیرساخت‌ها','این تصویب‌نامه نرخ حق تمبر برای اوراق و مدارک مختلف را بر اساس مواد ۴۰، ۴۰ مکرر و ۴۱ قانون مالیات‌های مستقیم تعیین می‌کند. حق تمبر نوعی مالیات غیرمستقیم است که بر اسناد و اوراق رسمی اعمال می‌شود و برای رسمیت بخشیدن و لازم‌الاجرا کردن آن‌ها ضروری است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:a12bdcfe1203','بخشنامه','111172/ت64434هـ','1404/07/13','آيين نامه اجرايي تبصره (1) ماده (3) قانون الزام به ثبت رسمي معاملات ام.....','تصویب‌نامه شماره ۱۱۱۱۷۲/ت۶۴۴۳۴هـ مورخ ۱۴۰۴/۰۷/۱۳ در خصوص آیین‌نامه اجرایی تبصره (۱) ماده (۳) قانون الزام به ثبت رسمی معاملات اموال غیرمنقول. مصوب جلسه مورخ ۱۴۰۴/۰۷/۰۲ هیئت وزیران. ماده ۳ قانون الزام: سازمان مکلف است پیش‌نویس قراردادها را با امکان کاهش یا افزایش شروط پیش‌نویس قراردادی به منظور استفاده دلالان معاملات املاک تهیه و در سامانه درج کند. تبصره ۱- درج ادعاها و مستندات در سامانه منوط به درج پلاک ثبتی و نقشه دارای مشخصات جغرافیایی (UTM) ابنیه، اراضی و املاک است.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره ۱ ماده ۳ قانون الزام به ثبت رسمی معاملات اموال غیرمنقول مصوب ۱۴۰۱','این آیین‌نامه اجرایی تبصره ۱ ماده ۳ قانون الزام به ثبت رسمی معاملات اموال غیرمنقول را اجرایی می‌کند. قانون الزام با هدف مقابله با معاملات عادی، شفاف‌سازی مالکیت و پیشگیری از دعاوی ملکی از تیر ۱۴۰۳ لازم‌الاجرا شده است. این آیین‌نامه نحوه تهیه پیش‌نویس قراردادها و درج ادعاها در سامانه را مشخص می‌کند و منوط به ثبت پلاک ثبتی و نقشه UTM ملک است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:3c977abe439f','بخشنامه','108013/ت64757هـ','1404/07/08','نصاب معاملات موضوع ماده 22 آیین‌نامه معاملات مالی و معاملاتی سازمان‌ها.....','تصویب‌نامه شماره ۱۰۸۰۱۳/ت۶۴۷۵۷هـ در خصوص تعیین نصاب معاملات موضوع ماده (۲۲) آیین‌نامه مالی و معاملاتی سازمان‌های مناطق آزاد تجاری-صنعتی برای سال ۱۴۰۵. نصاب معاملات برای سازمان‌های مناطق آزاد تعیین می‌شود: معاملات کوچک، متوسط و بزرگ بر اساس سقف‌های تعیین‌شده طبقه‌بندی می‌شوند. نصاب معاملات کوچک در سال ۱۴۰۴ معادل ۲٬۸۵۰٬۰۰۰٬۰۰۰ ریال (۲۸۵ میلیون تومان) بود.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','ماده ۲۲ آیین‌نامه مالی و معاملاتی سازمان‌های مناطق آزاد تجاری-صنعتی (موضوع تصویب‌نامه شماره ۱۵۹۰۹/ت۴۸۲۱۷ک مورخ ۱۳۹۲/۰۱/۳۱)','این تصویب‌نامه نصاب معاملات سازمان‌های مناطق آزاد تجاری-صنعتی را برای سال ۱۴۰۵ تعیین می‌کند. این نصاب‌ها بر اساس ماده ۲۲ آیین‌نامه مالی و معاملاتی مناطق آزاد تعیین شده و تعیین‌کننده نوع معامله (خرید مستقیم، استعلام بها یا مناقصه) در این سازمان‌ها است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:195717a7e6cf','بخشنامه','86558/ت63227هـ','1404/06/05','اصلاح ماده (3) آيين نامه اجرايي تبصره (7) ماده (39) قانون ماليات بر ار.....','تصویب‌نامه شماره ۸۶۵۵۸/ت۶۳۲۲۷هـ در خصوص اصلاح ماده (۳) آیین‌نامه اجرایی تبصره (۷) ماده (۳۹) قانون مالیات بر ارزش افزوده. تبصره ۷ ماده ۳۹: سهم عوارض ارزش افزوده دریافتی از شرکت‌های فناور مستقر در پارک‌های علم و فناوری پس از واریز به خزانه‌داری کل کشور، به صورت صددرصد (۱۰۰٪) به همان پارک یا مرکز رشد پرداخت می‌شود. ماده ۳ آیین‌نامه: عوارض ارزش افزوده شرکت‌های فناور مستقر در هر پارک توسط سازمان امور مالیاتی کشور هر ماه دریافت می‌شود.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره ۷ ماده ۳۹ قانون مالیات بر ارزش افزوده (سهم عوارض ارزش افزوده شرکت‌های فناور مستقر در پارک‌های علم و فناوری)','این تصویب‌نامه ماده ۳ آیین‌نامه اجرایی تبصره ۷ ماده ۳۹ قانون مالیات بر ارزش افزوده را اصلاح می‌کند. بر اساس تبصره ۷، عوارض ارزش افزوده دریافتی از شرکت‌های فناور مستقر در پارک‌های علم و فناوری به صورت ۱۰۰٪ به همان پارک پرداخت می‌شود تا از این طریق به توسعه فناوری و نوآوری حمایت شود.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:aad024f4af60','بخشنامه','83231/ت64554هـ','1404/05/28','اصلاح تصويب نامه شماره 14564/ت63885هـ مورخ 1404/2/2 با موضوع آيين نامه.....','تصویب‌نامه شماره ۸۳۲۳۱/ت۶۴۵۵۴هـ مورخ ۱۴۰۴/۰۵/۲۸ در خصوص اصلاح تصویب‌نامه شماره ۱۴۵۶۴/ت۶۳۸۸۵هـ مورخ ۱۴۰۴/۰۲/۰۲ با موضوع آیین‌نامه ایجاد صندوق‌های سرمایه‌گذاری املاک و مستغلات. اصلاحات: ۱- در ماده ۲، سقف سرمایه از «یک هزار میلیارد» به «یک میلیون میلیارد» افزایش یافت و عبارت «با تصویب شورای عالی بورس» اضافه شد. ۲- در ماده ۵، عبارت «با تصویب مراجع ذی‌ربط» برای واگذاری واحدهای سرمایه‌گذاری به بانک‌ها اضافه شد. ۳- در ماده ۸، شرط «با تأیید هیات عالی بانک مرکزی» برای واگذاری اموال اضافه شد. ۴- ماده ۱۰: معاملات صندوق موضوع تبصره ۱ ماده ۵ قانون جهش تولید مسکن از مالیات معاف است.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','اصل ۱۳۸ قانون اساسی، تصویب‌نامه شماره ۱۴۵۶۴/ت۶۳۸۸۵هـ مورخ ۱۴۰۴/۰۲/۰۲ (آیین‌نامه اصلی)، تبصره ۱ ماده ۵ قانون جهش تولید مسکن مصوب ۱۴۰۰، ماده ۹ آیین‌نامه اجرایی ماده ۵ قانون جهش تولید مسکن','این اصلاحیه با هدف تسهیل تشکیل صندوق‌های سرمایه‌گذاری املاک و مستغلات، سقف سرمایه را هزار برابر افزایش می‌دهد (از یک هزار میلیارد به یک میلیون میلیارد ریال). همچنین تقویت نظارت شورای عالی بورس و بانک مرکزی و معافیت مالیاتی معاملات این صندوق‌ها در راستای حمایت از قانون جهش تولید مسکن از جمله تغییرات است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:6d80018ca015','بخشنامه','78410/ت‌63745ﻫ','1404/05/21','آیین نامه اجرایی تبصره (8) ماده (10) قانون الزام به ثبت رسمی معاملات ا.....','تصویب‌نامه شماره ۷۸۴۱۰/ت۶۳۷۴۵هـ مورخ ۱۴۰۴/۰۵/۲۱ در خصوص آیین‌نامه اجرایی تبصره (۸) ماده (۱۰) قانون الزام به ثبت رسمی معاملات اموال غیرمنقول. مصوب جلسه ۱۴۰۴/۰۵/۰۸ هیئت وزیران. شامل ۱۵ ماده. ماده ۱- تعاریف (دستگاه مشمول، اموال مشمول شامل اراضی ملی، موات، ساحلی، موقوفات عام). ماده ۲- تکلیف دستگاه‌ها به درج نقشه و مستندات اموال فاقد سند رسمی ظرف ۲ سال در سامانه سادا. ماده ۵- تکلیف دستگاه‌ها به اقدام فوری برای دریافت سند رسمی. ماده ۶- اختیار وزارت اقتصاد برای صدور گواهی به نام دولت در صورت استنکاف دستگاه. ماده ۱۲- ضمانت اجرا: ممنوعیت پرداخت اعتبارات طرح‌های عمرانی و هزینه‌های آب و برق برای املاکی که در سامانه سادا ثبت نشده‌اند.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره ۸ ماده ۱۰ قانون الزام به ثبت رسمی معاملات اموال غیرمنقول مصوب ۱۴۰۱، ماده ۲۹ قانون برنامه ششم توسعه، ماده ۱۶ قانون برنامه هفتم پیشرفت، قانون جامع حدنگار (کاداستر) مصوب ۱۳۹۳','این آیین‌نامه با هدف شفاف‌سازی مالکیت‌های دولتی و عمومی تدوین شده است. دستگاه‌های اجرایی موظف‌اند ظرف ۲ سال اموال تحت مدیریت خود (اراضی ملی، موات، موقوفات عام و...) را در سامانه سادا ثبت و سند رسمی دریافت کنند. ضمانت اجرای این تکلیف، قطع بودجه‌های جاری و عمرانی ملک ثبت‌نشده است. این آیین‌نامه پیوستگی سیستمی بین وزارت اقتصاد و سازمان ثبت ایجاد می‌کند.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:0f1d629f5c6e','بخشنامه','77916/ت64365هـ','1404/05/20','آیین نامه اجرایی جزء (6-5-3) بند ب ماده 2 قانون تامین مالی تولید و زیر.....','تصویب‌نامه شماره ۷۷۹۱۶/ت۶۴۳۶۵هـ مورخ ۱۴۰۴/۰۵/۲۰ در خصوص آیین‌نامه اجرایی جزء ۶-۵-۳ بند ب ماده ۲ قانون تأمین مالی تولید و زیرساخت‌ها (موضوع رتبه‌بندی سطح فعالیت شرکت‌های اعتبارسنجی). مصوب جلسه ۱۴۰۴/۰۵/۰۸ هیئت وزیران. شامل ۶ ماده. ماده ۱- تعاریف (قانون، شورا، مرکز، بانک). ماده ۲- مرکز موظف است ظرف شش ماه از ابتدای هر سال، بر اساس معیارهای سابقه فعالیت، توان تخصصی و صحت‌سنجی، رتبه فعالیت در ۵ سطح به شرکت‌های اعتبارسنجی اعطا کند. ماده ۶- مشوق‌های رتبه‌بندی شامل افزایش کارمزد، تسهیل تمدید مجوز، امکان تأسیس شعبه.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','جزء ۶-۵-۳ بند ب ماده ۲ قانون تأمین مالی تولید و زیرساخت‌ها مصوب ۱۴۰۲، اجزای ۱-۵-۳، ۲-۵-۳، ۳-۵-۳ و ۷-۵-۳ همان قانون، ماده ۹ آیین‌نامه داخلی دولت','این آیین‌نامه نظام رتبه‌بندی برای شرکت‌های اعتبارسنجی ایجاد می‌کند. رتبه‌بندی در ۵ سطح و بر اساس معیارهای فنی، سوابق مدیران و دقت مدل‌های اعتبارسنجی انجام می‌شود. شرکت‌های برتر از مشوق‌هایی مانند افزایش کارمزد و تسهیل در تمدید مجوز برخوردار می‌شوند. هدف، ارتقای کیفیت خدمات اعتبارسنجی و شفاف‌سازی در بازار اعتبار است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:490470146d45','بخشنامه','76942/ت63562هـ','1404/05/19','اصلاحیه آیین نامه داخلی هیأت دولت','تصویب‌نامه شماره ۷۶۹۴۲/ت۶۳۵۶۲هـ مورخ ۱۴۰۴/۰۵/۱۹ در خصوص اصلاح ماده ۳۰ آیین‌نامه داخلی هیئت دولت و تبصره آن. مصوب جلسه ۱۴۰۴/۰۵/۱۲ هیئت وزیران. هدف: ایجاد انسجام و یکپارچگی در انتشار، ابلاغ و شیوه لازم‌الاجرا شدن مصوبات هیئت وزیران و تسهیل فرآیند ابلاغ مصوبات.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','اصل ۱۳۸ قانون اساسی، آیین‌نامه داخلی هیئت دولت (موضوع تصویب‌نامه شماره ۹۹/۱۲۰۰۰ مورخ ۱۳۷۸/۹/۱۸)','این تصویب‌نامه ماده ۳۰ آیین‌نامه داخلی هیئت دولت را اصلاح می‌کند تا فرآیند انتشار، ابلاغ و لازم‌الاجرا شدن مصوبات دولت یکپارچه و شفاف‌تر شود. هدف افزایش سرعت و انسجام در اجرای مصوبات هیئت وزیران است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:840b77f61a0c','بخشنامه','62980/ت64290هـ','1404/04/25','آیین نامه اجرایی بند (ش) تبصره 1 ماده واحده قانون بودجه سال 1404 کل کش.....','تصویب‌نامه شماره ۶۲۹۸۰/ت۶۴۲۹۰هـ در خصوص آیین‌نامه اجرایی بند (ش) تبصره (۱) ماده واحده قانون بودجه سال ۱۴۰۴ کل کشور (موضوع ثبت و شمول منافع حاصل از نگهداری وجوه اشخاص در اتاق‌های پایاپای در بازار سرمایه به عنوان مالیات بر درآمد). آیین‌نامه نحوه ثبت و شمول منافع حاصل از نگهداری وجوه اشخاص در اتاق‌های پایاپای بازار سرمایه به عنوان درآمد مشمول مالیات را مشخص می‌کند.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','بند (ش) تبصره (۱) ماده واحده قانون بودجه سال ۱۴۰۴ کل کشور، قانون مالیات بر ارزش افزوده','این آیین‌نامه نحوه ثبت و مالیات‌گیری منافع حاصل از نگهداری وجوه اشخاص در اتاق‌های پایاپای بازار سرمایه را بر اساس قانون بودجه ۱۴۰۴ تنظیم می‌کند. هدف، شفاف‌سازی معاملات پایاپای و شمول منافع آن به مالیات بر درآمد است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:a5fe1267577d','بخشنامه','62971/ت64371هـ','1404/04/25','اصلاح تصویبنامه امهال یا تقسیط مالیات واحدهای تولیدی آسیب دیده از قطع .....','تصویب‌نامه شماره ۶۲۹۷۱/ت۶۴۳۷۱هـ مورخ ۱۴۰۴/۰۴/۲۵ در خصوص اصلاح تصویب‌نامه امهال یا تقسیط مالیات واحدهای تولیدی آسیب‌دیده از قطع برق و گاز. اصلاح مصوبه قبلی (شماره ۱۹۳۲۶۰ مورخ ۱۴۰۳/۱۲/۱۳) که به پیشنهاد وزیر صنعت، معدن و تجارت و تأیید بانک مرکزی برای امهال، مساعدت و تقسیط بدهی بانکی و مالیاتی واحدهای تولیدی آسیب‌دیده از قطع برق و گاز تصویب شده بود.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تصویب‌نامه شماره ۱۹۳۲۶۰/ت۶۳۸۱۲هـ مورخ ۱۴۰۳/۱۲/۱۳ (مصوبه اصلی در خصوص امهال و تقسیط بدهی واحدهای تولیدی آسیب‌دیده از قطع برق و گاز)','این تصویب‌نامه اصلاحیه‌ای بر مصوبه قبلی است که به واحدهای تولیدی آسیب‌دیده از قطع برق و گاز امکان امهال و تقسیط بدهی‌های بانکی و مالیاتی را می‌داد. اصلاحیه شرایط و ضوابط این تسهیلات را به‌روزرسانی می‌کند تا حمایت از بنگاه‌های تولیدی آسیب‌دیده مؤثرتر باشد.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:1aeae3719c8f','بخشنامه','64356/62537','1404/04/25','خارج شدن تصویب نامه شماره 13400/م مورخ 1404/04/12 از طبقه بندی محرمانه.....','تصویب‌نامه شماره ۶۴۳۵۶/۶۲۵۳۷ در خصوص خارج شدن تصویب‌نامه شماره ۱۳۴۰۰/م مورخ ۱۴۰۴/۰۴/۱۲ از طبقه‌بندی محرمانه بودن. تصویب‌نامه ۱۳۴۰۰/م در خصوص اتخاذ تصمیماتی در خصوص پشتیبانی و حمایت از کالاها، واحدها و زنجیره‌های اولویت‌دار تولیدی و خدماتی و رفع موانع احتمالی آن‌ها تصویب شده بود. این تصویب‌نامه پس از خروج از طبقه محرمانه در دسترس عموم قرار گرفت.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تصویب‌نامه شماره ۱۳۴۰۰/م مورخ ۱۴۰۴/۰۴/۱۲ (بسته حمایتی از کالاها و واحدهای تولیدی)','این مصوبه، تصویب‌نامه ۱۳۴۰۰/م (بسته حمایتی دولت از واحدهای تولیدی پس از جنگ ۱۲ روزه) را از طبقه‌بندی محرمانه خارج می‌کند تا شفافیت افزایش یابد. تصویب‌نامه اصلی شامل تمهیدات ویژه برای حمایت از واحدهای تولیدی آسیب‌دیده از جمله تسهیلات بانکی و معافیت‌های مالیاتی است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:7e1274f6f054','بخشنامه','59880/ت63396هـ','1404/04/22','آيين نامه اجرايي تبصره 3 ماده 14 قانون الزام به ثبت رسمي معاملات اموال.....','تصویب‌نامه شماره ۵۹۸۸۰/ت۶۳۳۹۶هـ در خصوص آیین‌نامه اجرایی تبصره (۳) ماده (۱۴) قانون الزام به ثبت رسمی معاملات اموال غیرمنقول (موضوع مدیریت و ساماندهی پیش‌فروش ساختمان و مشارکت در ساخت). ماده ۱۴- سازمان مکلف است برای املاکی که دستور نقشه آن شامل تعداد طبقات، سطح اشغال مجاز و تعداد واحدهای هر طبقه توسط مراجع قانونی صادر شده است، پیش‌فروش واحدها را در سامانه ثبت کند. تبصره ۳- آیین‌نامه اجرایی این ماده توسط سازمان با همکاری وزارتخانه‌های کشور و راه و شهرسازی تهیه و به تصویب هیئت وزیران می‌رسد.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تبصره (۳) ماده (۱۴) قانون الزام به ثبت رسمی معاملات اموال غیرمنقول مصوب ۱۴۰۱','این آیین‌نامه نحوه مدیریت و ساماندهی پیش‌فروش ساختمان و مشارکت در ساخت را بر اساس قانون الزام به ثبت رسمی معاملات اموال غیرمنقول تنظیم می‌کند. هدف، جلوگیری از کلاهبرداری در پیش‌فروش املاک، شفاف‌سازی معاملات و حفظ حقوق خریداران است. پیش‌فروش تنها برای املاکی که دستور نقشه دارند مجاز است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:26a156fa1fde','بخشنامه','58822/ت63676هـ','1404/04/18','آیین نامه نحوه تاسیس، فعالیت و انحلال شرکت مدیریت دارایی های شبکه بانک.....','تصویب‌نامه شماره ۵۸۸۲۲/ت۶۳۶۷۶هـ مورخ ۱۴۰۴/۰۴/۱۸ در خصوص آیین‌نامه نحوه تأسیس، فعالیت و انحلال شرکت مدیریت دارایی‌های شبکه بانکی. مصوب جلسه ۱۴۰۴/۰۴/۰۸ هیئت وزیران. ماده ۵- مهم‌ترین وظایف شرکت: خرید اموال حسب درخواست بانک‌ها، مؤسسه‌های اعتباری یا صندوق، تملک اموال، بازاریابی و فروش اموال، قیمت‌گذاری و واگذاری دارایی‌ها و تسویه حساب. اساسنامه و ضوابط ناظر بر تأسیس، فعالیت و انحلال شرکت توسط بانک مرکزی تهیه می‌شود.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','جزء (۲۵) بند (ب) و بند (پ) ماده (۸) قانون برنامه پنج‌ساله هفتم پیشرفت جمهوری اسلامی ایران (۱۴۰۳-۱۴۰۷)','این آیین‌نامه نحوه تأسیس شرکت مدیریت دارایی‌های شبکه بانکی را بر اساس قانون برنامه هفتم مشخص می‌کند. این شرکت وظیفه خرید و مدیریت اموال تلسیس (دارایی‌های غیرمنقول وام‌گیرندگان) را بر عهده دارد تا بانک‌ها بتوانند مطالبات خود را وصول کنند و اموال به بازار منتقل شوند. هدف، رفع مشکل دارایی‌های مستغلات بانک‌ها و افزایش نقدینگی شبکه بانکی است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:c2de67da3ce9','بخشنامه','13400/م','1404/04/12','اتخاذ تصمیماتی در خصوص پشتیبانی و حمایت از كالاها، واحدها و زنجیره های.....','تصویب‌نامه شماره ۱۳۴۰۰/م مورخ ۱۴۰۴/۰۴/۱۲ در خصوص اتخاذ تصمیماتی در خصوص پشتیبانی و حمایت از کالاها، واحدها و زنجیره‌های اولویت‌دار تولیدی و خدماتی و رفع موانع احتمالی آن‌ها. شامل تمهیدات ویژه برای حمایت از واحدهای تولیدی آسیب‌دیده از جمله: تسهیلات بانکی با شرایط مساعد، تعویق و تقسیط بدهی‌های مالیاتی و گمرکی، تأمین سوخت و انرژی اولویت‌دار برای واحدهای تولیدی، و دستورالعمل‌های اجرایی مرتبط. تبصره ۱- با تأیید کمیسیون اقتصادی دولت، بانک مرکزی دستورالعمل اجرایی بند (۶) را به شبکه بانکی ابلاغ کرد.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','تصویب‌نامه شماره ۱۳۴۰۰/م مورخ ۱۴۰۴/۰۴/۱۲ هیئت وزیران (بسته حمایتی از کالاها، واحدها و زنجیره‌های تولیدی و خدماتی)','این تصویب‌نامه بسته حمایتی دولت برای حمایت از کالاها و واحدهای تولیدی آسیب‌دیده (به‌ویژه پس از جنگ ۱۲ روزه) است. شامل تسهیلات بانکی، تعویق بدهی‌های مالیاتی، تأمین انرژی و رفع موانع تولید است. این مصوبه ابتدا محرمانه بود و سپس از طبقه محرمانه خارج شد.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:77953d482e4c','بخشنامه','50703/ت63881هـ','1404/03/21','آيين نامه اجرايي بند (ر) تبصره (1) ماده واحده قانون بودجه سال 1404 كل .....','تصویب‌نامه شماره ۵۰۷۰۳/ت۶۳۸۸۱هـ مورخ ۱۴۰۴/۰۳/۱۷ در خصوص آیین‌نامه اجرایی بند (ر) تبصره (۱) ماده واحده قانون بودجه سال ۱۴۰۴ کل کشور (موضوع واردات خودروی سواری). مصوب جلسه ۱۴۰۴/۰۳/۲۱ هیئت وزیران. آیین‌نامه ضوابط و شرایط واردات خودروی سواری از محل بند ر تبصره ۱ قانون بودجه ۱۴۰۴ را مشخص می‌کند. شامل مقررات تفصیلی نحوه واردات، شرایط نمایندگی، تعرفه‌های گمرکی و الزامات فنی.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','بند (ر) تبصره (۱) ماده واحده قانون بودجه سال ۱۴۰۴ کل کشور (موضوع واردات خودروی سواری)','این آیین‌نامه ضوابط واردات خودروی سواری را بر اساس قانون بودجه ۱۴۰۴ مشخص می‌کند. شرایط نمایندگی جدید، نحوه واردات، تعرفه‌های گمرکی و الزامات فنی واردکنندگان در این آیین‌نامه آمده است. هدف، تنظیم بازار خودرو و ایجاد شفافیت در فرآیند واردات است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:f14343b4cab0','بخشنامه','46408/ت63970هـ','1404/03/17','آیین نامه اجرایی موضوع بند ت ماده 4 قانون برنامه پنجساله هفتم پیشرفت ج.....','تصویب‌نامه شماره ۴۶۴۰۸/ت۶۳۹۷۰هـ در خصوص آیین‌نامه اجرایی بند (ت) ماده (۴) قانون برنامه پنج‌ساله هفتم پیشرفت جمهوری اسلامی ایران (فهرست تلفیقی مالیات حقوق و کسور بیمه). مصوب جلسه ۱۴۰۴/۰۳/۱۱ هیئت وزیران. ماده ۹- در اجرای تبصره بند (ت) ماده (۴) قانون برنامه هفتم و ماده (۳۸) قانون تأمین اجتماعی، فهرست تلفیقی مالیات حقوق و کسور بیمه برای ساده‌سازی و یکپارچه‌سازی محاسبه و وصول مالیات حقوق و حق بیمه تأمین اجتماعی تدوین شده است.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','بند (ت) ماده (۴) قانون برنامه پنج‌ساله هفتم پیشرفت جمهوری اسلامی ایران (۱۴۰۳-۱۴۰۷)، ماده (۳۸) قانون تأأمین اجتماعی مصوب ۱۳۵۴','این آیین‌نامه فهرست تلفیقی مالیات حقوق و کسور بیمه را بر اساس بند ت ماده ۴ قانون برنامه هفتم ایجاد می‌کند. هدف، یکپارچه‌سازی و ساده‌سازی فرآیند محاسبه و وصول مالیات حقوق و حق بیمه تأمین اجتماعی از حقوق کارکنان است تا شفافیت و کارایی افزایش یابد.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
INSERT INTO public.circulars (source_id,kind,number,reg_date,subject,content,url,issuer,status,related_articles,interpretation,source_name) VALUES ('bakhshnameh_batch3:f4d3e0ac6794','بخشنامه','36633/ت63987هـ','1404/02/31','آیین نامه اجرایی بند ب ماده 31 و بند الف ماده 36 قانون تامین مالی تولی.....','تصویب‌نامه شماره ۳۶۶۳۳/ت۶۳۹۸۷هـ مورخ ۱۴۰۴/۰۲/۳۱ در خصوص آیین‌نامه اجرایی بند (ب) ماده (۳۱) و بند (الف) ماده (۳۶) قانون تأمین مالی تولید و زیرساخت‌ها. مصوب جلسه ۱۴۰۴/۰۲/۱۰ هیئت وزیران. این آیین‌نامه ضوابط اجرایی بندهای مذکور از قانون تأمین مالی تولید را که به نظارت بر بازار مالی و تأمین مالی تولید مرتبط هستند، مشخص می‌کند.','https://www.intamedia.ir/','هیئت وزیران','معتبر (دائمی)','بند (ب) ماده (۳۱) و بند (الف) ماده (۳۶) قانون تأمین مالی تولید و زیرساخت‌ها مصوب ۱۴۰۲','این آیین‌نامه اجرایی بند ب ماده ۳۱ و بند الف ماده ۳۶ قانون تأمین مالی تولید و زیرساخت‌ها را اجرایی می‌کند. موضوع مرتبط با نظارت بر بازار مالی، تأمین مالی تولید و ضوابط مربوط به آن است. قانون تأمین مالی تولید با هدف توسعه ابزارهای نوین تأمین مالی و حمایت از تولید مصوب شده است.','bakhshnameh_batch3') ON CONFLICT (source_id) DO NOTHING;
